WITH filtered AS (SELECT *, CEIL(age) AS age_whole, CASE WHEN segment IN ('Corporate', 'SMB') THEN 'Group A' ELSE 'Other' END AS segment_group FROM customers WHERE signup_date >= TO_DATE('2023-06-19') AND is_active) SELECT *, RANK() OVER (PARTITION BY country ORDER BY age DESC NULLS LAST) AS age_rank, CUME_DIST() OVER (PARTITION BY country ORDER BY age DESC NULLS FIRST) AS age_cume_dist, SUM(age_whole) OVER (PARTITION BY city, country ORDER BY credit_limit, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_age_whole FROM filtered
